#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *next; };
    struct Node b = {24, NULL};
    struct Node a = {12, &b};
    int count = 0;
    for (struct Node *cur = &a; cur != NULL; cur = cur->next) {
        count++;
    }
    printf("%d\n", count);
    return 0;
}

